mapper.select:
select flow_link_id, flow_id, cur_link, link_type, pre_link, next_link, user_type, role_id, org_id, msg_notify_type, leader_flag, sign_flag, rollback_flag, time_limit, attr_flag, alarm_flow_id, notify_admin_flag, msg_notify_limit, msg_notify_company from vm_flow_link_attr
AND flow_link_id = #{flowLinkId}
AND flow_id = #{flowId}
AND cur_link = #{curLink}
AND attr_flag = #{attrFlag}
AND alarm_flow_id = #{alarmFlowId}

select flow_link_id, flow_id, cur_link, link_type, pre_link, next_link, user_type, role_id, org_id, msg_notify_type, leader_flag, sign_flag, rollback_flag, time_limit, attr_flag, alarm_flow_id, notify_admin_flag, msg_notify_limit, msg_notify_company from vm_flow_link_attr
AND flow_id = #{flowId}
AND cur_link = #{curLink}
AND attr_flag = #{attrFlag}
AND alarm_flow_id = #{alarmFlowId}

select flow_link_id, flow_id, cur_link, link_type, pre_link, next_link, user_type, role_id, org_id, msg_notify_type, leader_flag, sign_flag, rollback_flag, time_limit, attr_flag, alarm_flow_id, notify_admin_flag, msg_notify_limit, msg_notify_company
from vm_flow_link_attr


		AND flow_link_id = #{flowLinkId}


		AND flow_id = #{flowId}


		AND cur_link = #{curLink}


		AND attr_flag = #{attrFlag}


		AND alarm_flow_id = #{alarmFlowId}

select flow_link_id, flow_id, cur_link, link_type, pre_link, next_link, user_type, role_id, org_id, msg_notify_type, leader_flag, sign_flag, rollback_flag, time_limit, attr_flag, alarm_flow_id, notify_admin_flag, msg_notify_limit, msg_notify_company
from vm_flow_link_attr where flow_id in

	#{flowId}

select fla.flow_link_id, fla.alarm_flow_id flow_id, fla.cur_link, fla.link_type, fla.pre_link, fla.next_link, fla.user_type, fla.role_id, fla.org_id, fla.msg_notify_type, fla.leader_flag, fla.sign_flag, fla.rollback_flag, fla.time_limit, fla.attr_flag, fla.alarm_flow_id, fla.notify_admin_flag, flc.link_name, fla.msg_notify_limit, fla.msg_notify_company from vm_flow_link_attr as fla left join vm_flow_link_config as flc on fla.cur_link = flc.link_id where fla.alarm_flow_id = #{alarmFlowId} and fla.cur_link in
#{curLink}
and attr_flag = '1'

SELECT dept_id AS deptId, dept_name AS deptName, parent_id AS parentId, dept_id AS nodeId, dept_name AS nodeName FROM sys_dept WHERE dept_id IN
#{deptId}
and tenant_id = #{tenantId}

SELECT dept_id AS deptId, dept_name AS deptName, parent_id AS parentId, dept_id AS nodeId, dept_name AS nodeName FROM sys_dept WHERE STATUS='0' and DEL_FLAG='0' and dept_id IN
#{deptId}
${param.dataScope}

SELECT dept_id AS deptId, dept_name AS deptName, parent_id AS parentId, dept_id AS nodeId, dept_name AS nodeName FROM sys_dept WHERE STATUS='0' and DEL_FLAG='0' and dept_id IN
#{deptId}
and tenant_id = #{param.tenantId}
and industry_code = #{param.industryCode}

select distinct sr.role_id as roleId, sr.role_name as roleName from sys_role as sr left join sys_user_role sur on sr.ROLE_ID = sur.role_id left join sys_user su on sur.USER_ID = su.USER_ID where su.DEPT_ID in
#{deptId}
or sr.role_type = '1'

select distinct su.user_id as userId, su.NICK_NAME as userName, su.dept_id as deptId, su.user_id as nodeId, su.user_name as nodeName, su.user_name as nickName, su.AVATAR as avatar from sys_user as su
left join sys_user_role as sur on su.user_id = sur.user_id
where su.DEL_FLAG='0' and su.STATUS='0' and
FIND_IN_SET( #{deptId} ,su.dept_id)
and su.tenant_id = #{model.tenantId}
and su.user_id IN
#{userId}
and sur.role_id IN
#{roleId}
group by su.user_id

select user_id
from vm_flow_link_user vla


		and vla.flow_link_id = #{flowLinkId}

SELECT sd.parent_id AS parentId, sd.dept_id AS deptId, sd.dept_name AS deptName, sd.dept_id AS nodeId, sd.dept_name AS nodeName, su.user_id AS u_userId, su.user_name AS u_userName, su.dept_id AS u_deptId, su.user_id AS u_nodeId, su.user_name AS u_nodeName FROM sys_dept sd left join sys_user su on sd.DEPT_ID = su.DEPT_ID and su.STATUS = '0' and su.DEL_FLAG = '0' where sd.DEL_FLAG = '0' and sd.STATUS = '0' and sd.dept_id in
#{deptId}
order by sd.DEPT_LEVEL
